package org.mcrf.client
import org.json.JSONArray
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test

class OpenFluxTeam016Test {
 @Test fun fluxFastPoolHasRoomForQuietTakeoverWithoutSlowingDirect(){val p=profile();assertEquals(60_000L,OpenFluxProfile.poolStartupMillis(p));p.getJSONArray("transports").getJSONObject(0).put("type","direct");assertEquals(15_000L,OpenFluxProfile.poolStartupMillis(p))}
 private fun profile()=JSONObject().put("type","openflux").put("name","UDP fixture").put("negotiate",true).put("secret","synthetic-secret-123456").put("context","kept-context").put("transports",JSONArray().put(JSONObject().put("type","fluxfast").put("name","udp-path").put("priority",90).put("dial","[::1]:32123")))
 private fun rejected(block:()->Unit){assertThrows(IllegalArgumentException::class.java){block()}}
 @Test fun fluxFastShareKeepsIdentityAndRequires016(){val raw=profile();val entry=OpenFluxProfile.link(OpenFluxProfile.share(raw));val c=requireNotNull(entry.carrier);assertTrue(OpenFluxProfile.requiresTeamCore(c));assertTrue(OpenFluxProfile.requiresFreshCore(c));assertEquals("kept-context",c.getString("context"));assertEquals("udp-path",c.getJSONArray("transports").getJSONObject(0).getString("name"));assertEquals("::1",entry.host.removeSurrounding("[","]"));assertEquals(32123,entry.port)}
 @Test fun fluxFastCannotDisableEncryptionOrUseStream(){for(field in listOf("secret","negotiate","mode")){val p=profile();when(field){"secret"->p.put(field,"");"negotiate"->p.put(field,false);else->p.put(field,"stream")};rejected{OpenFluxProfile.fromJson("fixture",p)}}}
 @Test fun fluxFastRejectsMalformedEndpoint(){for(value in listOf("host:0","host:65536","user@host:443","host:443/path","host:443?query","host:443#fragment","host")){val p=profile();p.getJSONArray("transports").getJSONObject(0).put("dial",value);rejected{OpenFluxProfile.fromJson("fixture",p)}}}
 @Test fun newSourcePinIsExactAndOldFreshSourceStaysSupported(){assertTrue(OpenFluxProfile.supportsTeamProfile("v0.16.0",OpenFluxProfile.TEAM_COMMIT));assertFalse(OpenFluxProfile.supportsTeamProfile("v0.16.1",OpenFluxProfile.TEAM_COMMIT));assertFalse(OpenFluxProfile.supportsTeamProfile("v0.16.0",OpenFluxProfile.FRESH_COMMIT));assertTrue(OpenFluxProfile.supportsFreshProfile(OpenFluxProfile.FRESH_VERSION,OpenFluxProfile.FRESH_COMMIT));assertFalse(OpenFluxProfile.requiresTeamCore(profile().apply {getJSONArray("transports").getJSONObject(0).put("type","direct")}))}
 @Test fun newCoreDoesNotInheritExperimentalVerificationOrScripts(){assertFalse(OpenFluxProfile.supportsVerification(OpenFluxProfile.TEAM_VERSION,OpenFluxProfile.TEAM_COMMIT,1,false,false));assertFalse(OpenFluxProfile.supportsScriptSource(OpenFluxProfile.TEAM_VERSION,OpenFluxProfile.TEAM_COMMIT));assertTrue(OpenFluxProfile.supportsScriptSource(OpenFluxProfile.FRESH_VERSION,OpenFluxProfile.FRESH_COMMIT))}
 @Test fun discoveryMigratesButOldSignedSourceIsStillRecognized(){assertEquals("OpenFluxTeam/OpenFlux",EngineUpdatePolicy.UPSTREAM);val old=JSONObject().put("repository",EngineUpdatePolicy.LEGACY_UPSTREAM).put("version",OpenFluxProfile.FRESH_VERSION).put("commit",OpenFluxProfile.FRESH_COMMIT);assertEquals(OpenFluxProfile.FRESH_COMMIT,EngineUpdatePolicy.source(old).commit);val team=JSONObject().put("repository",EngineUpdatePolicy.UPSTREAM).put("version",OpenFluxProfile.TEAM_VERSION).put("commit",OpenFluxProfile.TEAM_COMMIT);assertEquals(OpenFluxProfile.TEAM_COMMIT,EngineUpdatePolicy.source(team).commit);rejected{EngineUpdatePolicy.source(team.put("repository",EngineUpdatePolicy.LEGACY_UPSTREAM))};rejected{EngineUpdatePolicy.source(team.put("repository","attacker/OpenFlux"))}}
}
